const TIME_LIMIT: int = 1824;
const OPENING_BUFFER: int = 120;
const TH15_STAR_R: int = 608; // 源type16，同半径现代槽。

// st03:255–274：独立WAIT后VELTIME，方向哨兵保留当前角。
// 此处方向始终同速率方向，无后续逻辑标量读取，可用线性速度缓动。
xformdef death_bullet(delay: int, target: fx) {
    wait(delay);
    step_speed(target, 60);
}

async sub death_emitter() {
    // st03:238 flag288含禁交互位；发射体固定在死亡位置。
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var n: int = 1;
    var rounds: int = 4;
    var delay: int = 90;
    var target: fx = 4fx;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { n = 3; }
    if rank >= 2 { n = 5; }
    if rank == 3 { rounds = 8; delay = 40; target = 5fx; }
    // st03:227–229传给子敌的F0/I0/I1未被本发射sub读取。
    // st03:280–284每7帧重取一次自机角，mode1固定扇形。
    for burst in 0..rounds {
        var aim: angle = 90deg;
        if $player_x != $self_x || $player_y != $self_y {
            aim = atan2($player_y-$self_y, $player_x-$self_x);
        }
        for i in 0..n {
            var off: int = ((i+1)/2)*8192; // 0, -45, +45, -90, +90度
            if i%2 != 0 { off = -off; }
            var a: angle = aim + (off as angle);
            // st03:254 ANIM退位移保留；出生动画/减速/无判定整体省略。
            _ = fire(TH15_STAR_R, 6, $self_x-4.8fx*cos(a), $self_y-4.8fx*sin(a),
                     1.2fx, a, death_bullet(delay, target), none);
        }
        wait(7);
    }
    // st03:285 delete，仅移除发射体，不影响尾弹。
}

async sub source_enemy(dir: angle) {
    set_invuln(65535);
    // st03:206–207 圆形框取原宽度的一半。
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // st03:212–213 F0快照方向，120帧内由2线性增至3。
    move_vel(0, dir, 2fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    wait(120);
    // 任务批准：敌龄120仅触发一次死亡发弹，随后真实敌退场。
    // st03:230–231 清镜像并在父FINAL+(0,0)创建静止发射体。
    _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, death_emitter);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // st03:1540 源入口局部等待；三排分别从源70/330/590帧出生。
    wait(70);
    for row in 0..3 {
        var x: fx = -192fx;
        // 保留源逐次减0.017453rad；约每次减1度，按BAM量化。
        for i in 0..20 {
            var dir: angle = (16384 - ((i+1)*18204)/100) as angle;
            _ = spawn_enemy(x, -32fx, 100, 0, 0, 0, source_enemy(dir));
            x = x+17fx;
            wait(10);
        }
        if row < 2 { wait(60); }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
